const fs = require('fs');
const path = require('path');

// ============================================================
// generar_451_chat_v2.js
// ============================================================
// EL BUG PRINCIPAL DE LAS CAPTURAS
// Escribir "codifica", "calor", "vet" o "edad" respondia sobre el tema
// ANTERIOR. La causa: cuando no reconocia nada, heredaba el ultimo tema
// si la pregunta era corta.
//
// Ahora solo hereda con "y/pero/entonces" al principio. Lo demas es un
// tema nuevo, y si no se reconoce SE ADMITE:
//
//   "Eso esta fuera de lo que puedo consultar 🐾
//    Yo conozco la historia de Chiqui: lo que registras dia a dia, sus
//    cuidados y su salud. Sobre otros temas no se.
//    ¿Que quieres hacer?"
//   [📋 ¿Como ha estado?] [💉 Vacunas] [⚖️ Peso] [💊 Medicamentos]
//   [🧪 Examenes] [💡 Chiqui Tips]
//
// TRES COSAS NUEVAS
//
// 1. EMERGENCIAS, antes que todo lo demas. Si alguien escribe que su
//    mascota convulsiona, se desmayo, no respira, sangra, tuvo un golpe
//    de calor, se intoxico, la atropellaron o no puede caminar, no es
//    momento de conversar:
//
//      🚨 Una convulsion puede ser una urgencia.
//      · Aleja los objetos que tenga cerca
//      · Cronometra cuanto dura
//      · No lo sujetes ni le pongas nada en la boca
//      Si esta pasando ahora, ve al veterinario de inmediato.
//
//    No diagnostica: dice que hacer y que no hacer, que es lo unico
//    util en ese momento.
//
// 2. EL PESO CUENTA LA HISTORIA, no solo el numero:
//      🐾 Revise los registros de Chiqui.
//      Su ultimo peso fue 18,2 kg, del 12 ago. El anterior fue 17,5 kg.
//      Has registrado un aumento de 700 g.
//
// 3. DISEÑO ACTUALIZADO: burbujas con esquinas asimetricas como las
//    apps de mensajeria, indicador de "escribiendo" con tres puntos,
//    punto verde de disponible, y boton circular de enviar.
//
// PENDIENTE: que el veterinario de la familia revise los consejos y las
// instrucciones de emergencia.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '. Corre primero los scripts 440 y 447.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes('const EMERGENCIAS')) {
  abortar('el chat ya tiene esta version. Parece que este script ya se corrio.');
}
if (!actual.includes('const ALIMENTOS')) {
  abortar('falta la tabla de alimentos. Corre primero el script 440.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'",
  'export default function ChiquiChat',
  'const ALIMENTOS',
  'const EMERGENCIAS',
  'const INTENCIONES',
  'const CONSEJOS',
  'const AMBIGUAS',
  'const MENU',
  'puede ser una urgencia',
  'Eso está fuera de lo que puedo consultar',
  'No soy una inteligencia artificial',
  'chiquiPunto',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
// Las 8 emergencias.
for (const e of ['convuls', 'no respira', 'se desmayo', 'sangra mucho', 'golpe de calor', 'se intoxic', 'lo atropell', 'no puede caminar']) {
  if (!comp.includes(`'${e}`)) {
    abortar('falta la emergencia [' + e + '].');
  }
}
console.log('  OK  las 8 emergencias estan');

if (comp.split('type Tema =').length - 1 !== 1) {
  abortar('type Tema deberia declararse una sola vez.');
}
console.log('  OK  el contenido nuevo esta completo');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Listo. Admite cuando no sabe, reconoce urgencias y se ve actual.');
